   109	/**
   110	 * One late-error guard per physical stream. A capped write can still emit EPIPE
   111	 * after its foreground command returns; keeping the per-run listener would grow
   112	 * without bound when a stream never settles. This shared guard is reference
   113	 * counted by pending writes, so it contains that late event while retaining at
   114	 * most one listener for any stream and disappears once the final write settles.
   115	 */
   116	const lateStreamErrorGuards = new WeakMap<HostRunOutputStream, {
   117	  pending: number;
   118	  listener: (error: Error) => void;
   119	}>();
   120	
   121	function retainLateStreamErrorContainment(stream: HostRunOutputStream): () => void {
   122	  let guard = lateStreamErrorGuards.get(stream);
   123	  if (!guard) {
   124	    guard = { pending: 0, listener: () => { /* late EPIPE is intentionally contained */ } };
   125	    lateStreamErrorGuards.set(stream, guard);
   126	    stream.on('error', guard.listener);
   127	  }
   128	  guard.pending += 1;
   129	  let released = false;
   130	  return () => {
   131	    if (released) return;
   132	    released = true;
   133	    const current = lateStreamErrorGuards.get(stream);
   134	    if (!current) return;
   135	    current.pending -= 1;
   136	    if (current.pending <= 0) {
   137	      stream.removeListener('error', current.listener);
